# bash completion for protodial; generated by `protodial completion bash`.
_protodial_complete()
{
    local value description append_space current replacement character previous
    local line_before_cursor quote quote_kind quoted_replacement
    local cursor_word index replacement_start escaped
    local -a completion_words
    current=${COMP_WORDS[COMP_CWORD]}
    completion_words=("${COMP_WORDS[@]:1}")
    line_before_cursor=
    if [[ -n ${COMP_LINE+x} && -n ${COMP_POINT+x} ]]; then
        line_before_cursor=${COMP_LINE:0:COMP_POINT}
    fi
    quote=
    quote_kind=
    escaped=0
    cursor_word=
    for ((index = 0; index < ${#line_before_cursor}; index++)); do
        character=${line_before_cursor:index:1}
        if [[ $quote == "'" ]]; then
            if [[ $character == "'" ]]; then
                quote=
                quote_kind=
            else
                cursor_word=${cursor_word}${character}
            fi
        elif ((escaped)); then
            cursor_word=${cursor_word}${character}
            escaped=0
        elif [[ $character == \\ ]]; then
            escaped=1
        elif [[ $quote == '"' ]]; then
            if [[ $character == '"' ]]; then
                quote=
                quote_kind=
            else
                cursor_word=${cursor_word}${character}
            fi
        elif [[ $character == "'" || $character == '"' ]]; then
            quote=$character
            quote_kind=$character
            if [[ $character == "'" && $index -gt 0 ]]; then
                previous=${line_before_cursor:$((index - 1)):1}
                if [[ $previous == '$' ]]; then
                    quote_kind=ansi
                    cursor_word=${cursor_word:0:${#cursor_word}-1}
                fi
            fi
        elif [[ $character == ' ' || $character == $'\t' \
            || $character == $'\n' ]]; then
            cursor_word=
        else
            cursor_word=${cursor_word}${character}
        fi
    done
    if [[ -n ${COMP_LINE+x} && -n ${COMP_POINT+x} ]]; then
        current=$cursor_word
        completion_words[COMP_CWORD-1]=$cursor_word
    fi
    COMPREPLY=()
    while IFS= read -r -d '' value \
        && IFS= read -r -d '' description \
        && IFS= read -r -d '' append_space; do
        replacement_start=0
        if [[ -z $quote ]]; then
            for ((index = 0; index < ${#current}; index++)); do
                character=${current:index:1}
                if [[ $COMP_WORDBREAKS == *"$character"* ]]; then
                    replacement_start=$((index + 1))
                fi
            done
        fi
        replacement=${value:replacement_start}
        # Readline inserts COMPREPLY text verbatim for -F completions. Quote
        # only the segment it replaces, so metacharacters remain literal and
        # existing text before a word break (such as '=' or ':') is retained.
        if [[ $quote_kind == ansi ]]; then
            quoted_replacement=
            for ((index = 0; index < ${#replacement}; index++)); do
                character=${replacement:index:1}
                case $character in
                    "'"|\\)
                        quoted_replacement="${quoted_replacement}\\${character}"
                        ;;
                    *) quoted_replacement="${quoted_replacement}${character}" ;;
                esac
            done
            replacement=$quoted_replacement
        elif [[ $quote == "'" ]]; then
            quoted_replacement=
            for ((index = 0; index < ${#replacement}; index++)); do
                character=${replacement:index:1}
                if [[ $character == "'" ]]; then
                    # Close the quote, emit an escaped quote, and reopen it.
                    quoted_replacement="${quoted_replacement}'\\''"
                else
                    quoted_replacement="${quoted_replacement}${character}"
                fi
            done
            replacement=$quoted_replacement
        elif [[ $quote == '"' ]]; then
            quoted_replacement=
            for ((index = 0; index < ${#replacement}; index++)); do
                character=${replacement:index:1}
                case $character in
                    '!')
                        # History expansion remains active inside double
                        # quotes.  Move just the bang through a single-quoted
                        # segment so argv receives `!`, never `\!`.
                        quoted_replacement="${quoted_replacement}\"'!'\""
                        ;;
                    '"'|\\|'$'|'`')
                        quoted_replacement="${quoted_replacement}\\${character}"
                        ;;
                    *) quoted_replacement="${quoted_replacement}${character}" ;;
                esac
            done
            replacement=$quoted_replacement
        else
            printf -v quoted_replacement '%q' "$replacement"
            replacement=$quoted_replacement
        fi
        # Readline closes an active quote itself.  A manually appended space
        # would otherwise land inside that quote, so only add it in the
        # unquoted case.
        if [[ $append_space == 1 && -z $quote ]]; then
            replacement="$replacement "
        fi
        COMPREPLY+=("$replacement")
    done < <(printf '%s\0' "${completion_words[@]}" \
        | command protodial __complete --protocol=protodial-v1 --shell bash \
            --cursor "$((COMP_CWORD - 1))" --words-stdin 2>/dev/null)
}

complete -o nospace -F _protodial_complete protodial
